mapper.update:
UPDATE afv_remote_generation_job SET state = 'RUNNING', owner_instance_id = #{owner},
    owner_epoch = owner_epoch + 1, lease_until = TIMESTAMPADD(SECOND, 90, UTC_TIMESTAMP(6)),
    permit_held = #{permitHeld}, revision = revision + 1, updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}

UPDATE afv_remote_generation_job SET state = 'CANCELLED', phase = 'FINISHED', permit_held = FALSE,
    error_code = 'CANCELLED_BEFORE_SUBMISSION', error_message = '已取消排队，尚未提交供应商',
    revision = revision + 1, updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}

UPDATE afv_remote_generation_job j JOIN afv_generation_attempt a ON a.id = #{attemptId}
SET j.state = 'WAITING', j.phase = CASE WHEN a.result_json IS NULL THEN 'POLLING' ELSE 'INGESTING' END, j.active_attempt_id = a.id,
    j.provider_task_id = a.provider_task_id, j.result_json = a.result_json,
    j.permit_held = (a.result_json IS NULL), j.next_poll_at = UTC_TIMESTAMP(6),
    j.deadline_at = TIMESTAMPADD(HOUR, 2, UTC_TIMESTAMP(6)), j.consecutive_errors = 0,
    j.error_code = NULL, j.error_message = NULL, j.revision = j.revision + 1 WHERE j.id = #{id}

UPDATE afv_remote_generation_job SET state = 'WAITING', phase = 'SUBMITTING',
    next_poll_at = UTC_TIMESTAMP(6), deadline_at = TIMESTAMPADD(HOUR, 2, UTC_TIMESTAMP(6)),
    consecutive_errors = 0, error_code = NULL, error_message = NULL, revision = revision + 1 WHERE id = #{id}

UPDATE afv_remote_generation_job SET state = 'WAITING', phase = 'INGESTING', permit_held = FALSE,
    next_poll_at = UTC_TIMESTAMP(6), consecutive_errors = 0, error_code = NULL, error_message = NULL,
    revision = revision + 1 WHERE id = #{id}

UPDATE afv_remote_generation_job SET state = #{state}, phase = 'FINISHED', permit_held = FALSE,
    error_code = 'PROVIDER_FINISHED_CONFIRMED', error_message = #{message},
    revision = revision + 1, updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}

UPDATE afv_remote_generation_job SET state = 'CANCELLED', phase = 'FINISHED', cancel_requested = TRUE, permit_held = FALSE,
    owner_instance_id = NULL, lease_until = NULL, owner_epoch = owner_epoch + 1,
    error_code = 'ADMIN_CONFIRMED_FINISHED', error_message = #{message}, revision = revision + 1, updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}
